namespace Payments;

public interface IPaymentProvider
{
    Task<ProviderChargeResponse> CreateChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<ProviderRefundResponse> CreateRefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;
    private const decimal MinimumAmount = 0.50m;
    private const decimal MaximumAmount = 999_999.99m;

    public PaymentGateway(IPaymentProvider provider)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("Card token is required.", nameof(cardToken));

        if (amount < MinimumAmount)
            throw new ArgumentOutOfRangeException(nameof(amount), amount, $"Amount must be at least {MinimumAmount}.");

        if (amount > MaximumAmount)
            throw new ArgumentOutOfRangeException(nameof(amount), amount, $"Amount must not exceed {MaximumAmount}.");

        try
        {
            var response = await _provider.CreateChargeAsync(cardToken, amount, cancellationToken);
            return new ChargeResult(response.ChargeId, response.Succeeded);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception ex)
        {
            return new ChargeResult(string.Empty, Success: false, ex.Message);
        }
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(chargeId))
            throw new ArgumentException("Charge ID is required.", nameof(chargeId));

        try
        {
            var response = await _provider.CreateRefundAsync(chargeId, cancellationToken);
            return new RefundResult(response.RefundId, response.Succeeded);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception ex)
        {
            return new RefundResult(string.Empty, Success: false, ex.Message);
        }
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        if (string.IsNullOrWhiteSpace(eventType))
            throw new ArgumentException("Event type is required.", nameof(eventType));

        if (string.IsNullOrWhiteSpace(payload))
            throw new ArgumentException("Payload is required.", nameof(payload));

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(WebhookAction.ChargeCompleted, payload),
            "charge.failed" => new WebhookResult(WebhookAction.ChargeFailed, payload),
            "refund.succeeded" => new WebhookResult(WebhookAction.RefundCompleted, payload),
            "refund.failed" => new WebhookResult(WebhookAction.RefundFailed, payload),
            _ => new WebhookResult(WebhookAction.Unknown, payload),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success, string? ErrorMessage = null);
public record RefundResult(string RefundId, bool Success, string? ErrorMessage = null);
public record WebhookResult(WebhookAction Action, string Payload);

public record ProviderChargeResponse(string ChargeId, bool Succeeded);
public record ProviderRefundResponse(string RefundId, bool Succeeded);

public enum WebhookAction
{
    Unknown,
    ChargeCompleted,
    ChargeFailed,
    RefundCompleted,
    RefundFailed,
}

