namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    #region Constructor

    [TestMethod]
    public void Constructor_NullProvider_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — validation

    [TestMethod]
    [DataRow(null, DisplayName = "Null token")]
    [DataRow("", DisplayName = "Empty token")]
    [DataRow("   ", DisplayName = "Whitespace token")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? cardToken)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10m));

        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0.00, DisplayName = "Zero")]
    [DataRow(-5.00, DisplayName = "Negative")]
    [DataRow(0.49, DisplayName = "Below minimum")]
    public async Task ChargeAsync_AmountBelowMinimum_ThrowsArgumentOutOfRangeException(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));

        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_AmountAboveMaximum_ThrowsArgumentOutOfRangeException()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000.00m));

        Assert.AreEqual("amount", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — success

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_ReturnsSuccessfulCharge()
    {
        _provider.ChargeResponse = new ProviderChargeResponse("ch_123", Succeeded: true);

        var result = await _gateway.ChargeAsync("tok_valid", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsNull(result.ErrorMessage);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_PassesParametersToProvider()
    {
        await _gateway.ChargeAsync("tok_abc", 75.00m);

        Assert.AreEqual("tok_abc", _provider.LastCardToken);
        Assert.AreEqual(75.00m, _provider.LastAmount);
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 0.50m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_MaximumAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 999_999.99m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclines_ReturnsUnsuccessfulCharge()
    {
        _provider.ChargeResponse = new ProviderChargeResponse("ch_declined", Succeeded: false);

        var result = await _gateway.ChargeAsync("tok_valid", 10m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual("ch_declined", result.ChargeId);
    }

    #endregion

    #region ChargeAsync — error handling

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ReturnsFailureWithErrorMessage()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Network timeout");

        var result = await _gateway.ChargeAsync("tok_valid", 10m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.ChargeId);
        Assert.AreEqual("Network timeout", result.ErrorMessage);
    }

    [TestMethod]
    public async Task ChargeAsync_CancellationRequested_ThrowsOperationCanceledException()
    {
        using var cts = new CancellationTokenSource();
        await cts.CancelAsync();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m, cts.Token));
    }

    #endregion

    #region RefundAsync — validation

    [TestMethod]
    [DataRow(null, DisplayName = "Null chargeId")]
    [DataRow("", DisplayName = "Empty chargeId")]
    [DataRow("   ", DisplayName = "Whitespace chargeId")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));

        Assert.AreEqual("chargeId", ex.ParamName);
    }

    #endregion

    #region RefundAsync — success

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessfulRefund()
    {
        _provider.RefundResponse = new ProviderRefundResponse("re_456", Succeeded: true);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsTrue(result.Success);
        Assert.AreEqual("re_456", result.RefundId);
        Assert.IsNull(result.ErrorMessage);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_PassesChargeIdToProvider()
    {
        await _gateway.RefundAsync("ch_abc");

        Assert.AreEqual("ch_abc", _provider.LastChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderDeclines_ReturnsUnsuccessfulRefund()
    {
        _provider.RefundResponse = new ProviderRefundResponse("re_declined", Succeeded: false);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
        Assert.AreEqual("re_declined", result.RefundId);
    }

    #endregion

    #region RefundAsync — error handling

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ReturnsFailureWithErrorMessage()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Service unavailable");

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.RefundId);
        Assert.AreEqual("Service unavailable", result.ErrorMessage);
    }

    [TestMethod]
    public async Task RefundAsync_CancellationRequested_ThrowsOperationCanceledException()
    {
        using var cts = new CancellationTokenSource();
        await cts.CancelAsync();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.RefundAsync("ch_123", cts.Token));
    }

    #endregion

    #region ProcessWebhook — validation

    [TestMethod]
    [DataRow(null, "payload", "eventType", DisplayName = "Null eventType")]
    [DataRow("", "payload", "eventType", DisplayName = "Empty eventType")]
    [DataRow("charge.succeeded", null, "payload", DisplayName = "Null payload")]
    [DataRow("charge.succeeded", "", "payload", DisplayName = "Empty payload")]
    public void ProcessWebhook_InvalidArgument_ThrowsArgumentException(
        string? eventType, string? payload, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, payload!));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    #endregion

    #region ProcessWebhook — event routing

    [TestMethod]
    [DataRow("charge.succeeded", WebhookAction.ChargeCompleted)]
    [DataRow("charge.failed", WebhookAction.ChargeFailed)]
    [DataRow("refund.succeeded", WebhookAction.RefundCompleted)]
    [DataRow("refund.failed", WebhookAction.RefundFailed)]
    public void ProcessWebhook_KnownEventType_ReturnsExpectedAction(
        string eventType, WebhookAction expectedAction)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(expectedAction, result.Action);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEventType_ReturnsUnknownAction()
    {
        var result = _gateway.ProcessWebhook("dispute.created", "{\"id\":\"evt_2\"}");

        Assert.AreEqual(WebhookAction.Unknown, result.Action);
    }

    [TestMethod]
    public void ProcessWebhook_ValidEvent_PreservesPayload()
    {
        const string payload = "{\"id\":\"evt_3\",\"amount\":100}";

        var result = _gateway.ProcessWebhook("charge.succeeded", payload);

        Assert.AreEqual(payload, result.Payload);
    }

    #endregion
}

