namespace Payments.Tests;

internal sealed class FakePaymentProvider : IPaymentProvider
{
    public ProviderChargeResponse? ChargeResponse { get; set; }
    public ProviderRefundResponse? RefundResponse { get; set; }
    public Exception? ExceptionToThrow { get; set; }

    public string? LastCardToken { get; private set; }
    public decimal? LastAmount { get; private set; }
    public string? LastChargeId { get; private set; }

    public Task<ProviderChargeResponse> CreateChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();

        LastCardToken = cardToken;
        LastAmount = amount;

        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        return Task.FromResult(ChargeResponse ?? new ProviderChargeResponse("ch_default", true));
    }

    public Task<ProviderRefundResponse> CreateRefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();

        LastChargeId = chargeId;

        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        return Task.FromResult(RefundResponse ?? new ProviderRefundResponse("re_default", true));
    }
}

